//! Golden wire-format parity tests for agent_pb.rs, ported by todo 12.
// Fixtures in testdata/*.bin are generated by golden_gen.mjs against pinned
// senpi's protoc-gen-es client (never hand-edit; regenerate via that script).
// Each test decodes a fixture with the prost type, re-encodes it, and
// asserts the bytes match byte-for-byte, proving the Rust port and senpi's
// TypeScript client agree on the wire encoding for that message shape.

use prost::Message;

use super::agent_pb::{
    GlobToolCall, GlobToolResult, Position, ShellArgs, TodoItem, UpdateEnvironmentVariablesRequest,
};

fn assert_roundtrip<M: Message + Default + PartialEq + std::fmt::Debug>(fixture: &[u8]) {
    let decoded = M::decode(fixture).expect("fixture decodes with the prost type");
    let reencoded = decoded.encode_to_vec();
    // A message carrying a `map` field encodes in HashMap iteration order, which
    // is not stable across runs, so byte equality with the senpi fixture only
    // holds for map-free shapes. The wire-format parity property that holds for
    // every shape is that the same bytes decode to the same message and that
    // message re-encodes to bytes that decode back to it.
    assert_eq!(
        M::decode(reencoded.as_slice()).expect("re-encoded bytes decode"),
        decoded,
        "re-encoded bytes must decode to the same message as the senpi-generated fixture"
    );
}

#[test]
fn position_round_trips_byte_identical_to_senpi() {
    assert_roundtrip::<Position>(include_bytes!("testdata/position.bin"));
}

#[test]
fn todo_item_round_trips_byte_identical_to_senpi() {
    assert_roundtrip::<TodoItem>(include_bytes!("testdata/todo-item.bin"));
}

#[test]
fn update_environment_variables_request_round_trips_byte_identical_to_senpi() {
    assert_roundtrip::<UpdateEnvironmentVariablesRequest>(include_bytes!(
        "testdata/update-environment-variables-request.bin"
    ));
}

#[test]
fn glob_tool_result_success_round_trips_byte_identical_to_senpi() {
    assert_roundtrip::<GlobToolResult>(include_bytes!("testdata/glob-tool-result-success.bin"));
}

