#[test]
fn glob_tool_result_success_decodes_expected_field_values() {
    let fixture = include_bytes!("testdata/glob-tool-result-success.bin");
    let decoded = GlobToolResult::decode(fixture.as_slice()).expect("fixture decodes");
    match decoded.result {
        Some(super::agent_pb::glob_tool_result::Result::Success(success)) => {
            assert_eq!(success.pattern, "*.ts");
            assert_eq!(success.path, "/src");
            assert_eq!(success.files, vec!["a.ts".to_string(), "b.ts".to_string()]);
            assert_eq!(success.total_files, 2);
            assert!(!success.client_truncated);
            assert!(success.ripgrep_truncated);
        }
        other => panic!("expected GlobToolResult::Success, got {other:?}"),
    }
}

#[test]
fn shell_args_decodes_expected_optional_and_nested_fields() {
    let fixture = include_bytes!("testdata/shell-args.bin");
    let decoded = ShellArgs::decode(fixture.as_slice()).expect("fixture decodes");
    assert_eq!(decoded.command, "ls -la");
    assert_eq!(decoded.working_directory, "/tmp");
    assert_eq!(decoded.timeout, 30);
    assert_eq!(decoded.tool_call_id, "tc-1");
    assert_eq!(decoded.simple_commands, vec!["ls".to_string()]);
    assert_eq!(decoded.file_output_threshold_bytes, Some(4096));
    assert!(decoded.skip_approval);
    assert_eq!(decoded.hard_timeout, Some(60_000));
    assert_eq!(decoded.description, Some("list files".to_string()));
    assert_eq!(decoded.conversation_id, Some("conv-1".to_string()));
    let sandbox = decoded
        .requested_sandbox_policy
        .expect("requested_sandbox_policy is set");
    assert_eq!(sandbox.r#type, 2);
    assert_eq!(sandbox.network_access, Some(true));
}
